#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-10-08
/**
 * The docs Playwright install can never hang the required Docs Site Build (#4665).
 *
 * THE FAILURE
 *
 *   `npx playwright install --with-deps chromium` hung three times on
 *   2026-10-07 (jobs 112950356919, 112961977648, 113017086059) until the job
 *   was cancelled at about 21 minutes. All three stopped in the SAME place,
 *   before any browser download: the `--with-deps` apt update. The Azure
 *   Ubuntu mirror stopped answering, apt fell back to archive.ubuntu.com, and
 *   the log went silent for 20 minutes after `noble-security InRelease`.
 *
 * THE INVARIANT, per arm
 *
 *   cache:    ~/.cache/ms-playwright is cached under a key that names the
 *             installed Playwright version, so a hit skips the download.
 *   no-combo: no step runs the unbounded `playwright install --with-deps`.
 *   apt:      apt gets network timeouts before the system-deps step, so a
 *             dead mirror fails in seconds instead of stalling.
 *   bounded:  every step that runs `playwright install` (browser or deps)
 *             has timeout-minutes of at most 5 and retries once, each
 *             attempt under its own `timeout`.
 */
import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
// js-yaml is a declared dependency of src/hooks, and the CI job that runs
// tests/ci installs src/hooks deps only. The root package.json has no YAML
// parser, so resolve from src/hooks, not from the root.
const require = createRequire(join(ROOT, 'src/hooks/package.json'));
const yaml = require('js-yaml');

const wf = yaml.load(readFileSync(join(ROOT, '.github/workflows/docs.yml'), 'utf8'));
const failures = [];
const fail = (arm, msg) => failures.push(`${arm}: ${msg}`);

// The job that runs the docs Playwright e2e.
const job = Object.values(wf.jobs).find((j) =>
  (j.steps || []).some((s) => /playwright test/.test(s.run || '')),
);
if (!job) {
  console.error('FAIL: no docs.yml job runs `playwright test`; the scan is broken');
  process.exit(1);
}
const steps = job.steps;
const runOf = (s) => String(s.run || '');

// cache
const cache = steps.find(
  (s) => /^actions\/cache@/.test(String(s.uses || '')) && /ms-playwright/.test(String(s.with?.path || '')),
);
if (!cache) fail('cache', 'no actions/cache step for ~/.cache/ms-playwright');
else if (!/playwright/i.test(String(cache.with?.key || '')) || !/\$\{\{\s*steps\.[\w-]+\.outputs\.version\s*\}\}/.test(String(cache.with?.key || ''))) {
  fail('cache', `cache key does not name the Playwright version: ${cache.with?.key}`);
}

// no-combo
for (const s of steps) {
  if (/playwright install[^\n]*--with-deps/.test(runOf(s))) fail('no-combo', `step "${s.name}" still runs install --with-deps`);
}

// apt
const depsIdx = steps.findIndex((s) => /playwright install-deps/.test(runOf(s)));
const aptIdx = steps.findIndex((s) => /Acquire::https?::Timeout/.test(runOf(s)));
if (depsIdx === -1) fail('apt', 'no `playwright install-deps` step');
else if (aptIdx === -1 || aptIdx > depsIdx) fail('apt', 'apt network timeouts are not set before install-deps');

// bounded
const installs = steps.filter((s) => /playwright install/.test(runOf(s)));
if (installs.length === 0) fail('bounded', 'no playwright install step found');
for (const s of installs) {
  const tm = Number(s['timeout-minutes']);
  if (!(tm > 0 && tm <= 5)) fail('bounded', `step "${s.name}" has timeout-minutes ${s['timeout-minutes']}, want 1 to 5`);
  if (!/for attempt in 1 2\b/.test(runOf(s))) fail('bounded', `step "${s.name}" does not retry once`);
  if (!/\btimeout \d+ npx playwright install/.test(runOf(s))) fail('bounded', `step "${s.name}" has no per-attempt timeout`);
}

if (failures.length) {
  for (const f of failures) console.error(`FAIL ${f}`);
  process.exit(1);
}
console.log(`PASS: docs Playwright install is cached and bounded (${installs.length} install steps)`);
